MAKE CODE: P1AM-100 Motor Start/Stop with Seal-in
language arduino
// P1AM-100: Motor Start/Stop with Seal-in
// Slot 1: Discrete Input Module
//   Channel 1: Start Button (Normally Open)
//   Channel 2: Stop Button (Normally Closed)
// Slot 2: Discrete Output Module
//   Channel 1: Motor Contactor
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  // Wait for the P1AM modules to initialize
  while (!P1.init()) {
    ; // Spin until modules are ready
  }
}

void loop() {
  // Read inputs
  // Start is NO: true when pressed
  bool startPressed = P1.readDiscrete(inSlot, 1);

  // Stop is NC: true when NOT pressed (circuit closed), false when pressed (circuit open)
  bool stopPressed = !P1.readDiscrete(inSlot, 2);

  // Logic: Motor runs if Start is pressed OR it is already running,
  // AND Stop is not pressed (and no overload, though not requested here).
  motorRunning = (startPressed || motorRunning) && stopPressed;

  // Write output
  // Channel 1 drives the motor contactor
  P1.writeDiscrete(motorRunning, outSlot, 1);
}
END

